import { render } from '@solidjs/web';
import { createSignal, createEffect } from 'solid-js';
import './styles.css';

function ThemePicker() {
  const [theme, setTheme] = createSignal('light');
  const [label, setLabel] = createSignal('');

  // A derived value in disguise: replace this with a function.
  createEffect(theme, (value) => {
    setLabel(`Using the ${value} theme`);
  });

  return (
    <>
      <select onChange={(event) => setTheme(event.currentTarget.value)}>
        <option value="light">Light</option>
        <option value="dark">Dark</option>
        <option value="sepia">Sepia</option>
      </select>
      <p>{label()}</p>
    </>
  );
}

render(() => <ThemePicker />, document.getElementById('app'));

body {
  font-family: sans-serif;
  transition: background 0.3s, color 0.3s;
}

body.dark {
  background: #1e1e2e;
  color: #eee;
}

body.sepia {
  background: #f4ecd8;
  color: #5b4636;
}

import { render } from '@solidjs/web';
import { createSignal, createEffect } from 'solid-js';
import './styles.css';

function ThemePicker() {
  const [theme, setTheme] = createSignal('light');
  const label = () => `Using the ${theme()} theme`;

  createEffect(theme, (value) => {
    document.body.classList.add(value);
    return () => document.body.classList.remove(value);
  });

  return (
    <>
      <select onChange={(event) => setTheme(event.currentTarget.value)}>
        <option value="light">Light</option>
        <option value="dark">Dark</option>
        <option value="sepia">Sepia</option>
      </select>
      <p>{label()}</p>
    </>
  );
}

render(() => <ThemePicker />, document.getElementById('app'));

body {
  font-family: sans-serif;
  transition: background 0.3s, color 0.3s;
}

body.dark {
  background: #1e1e2e;
  color: #eee;
}

body.sepia {
  background: #f4ecd8;
  color: #5b4636;
}
